insert into public.brand_profiles (id, workspace_id, name, positioning, tone_of_voice, avoid_terms, preferred_terms, colors, logo_asset_path, is_default, created_by) values
  ('0b4a0d01-0000-4000-8000-000000000001','0a11b0a1-0000-4000-8000-000000000001','A&M Unternehmerberatung','A&M begleitet inhabergeführte mittelständische Unternehmen dabei, ihre Ertragskraft messbar zu steigern. Kein Konzernberatungs-Theater, sondern Zahlen, Klartext und Umsetzung an der Seite der Geschäftsführung.','Direkt, sachlich, unternehmerisch. Wir sprechen Geschäftsführerinnen und Geschäftsführer auf Augenhöhe an, belegen jede Aussage mit einer Zahl und verzichten vollständig auf Superlative und Marketingfloskeln.',array['günstig','billig','Schnäppchen','garantiert','revolutionär','Marktführer','Weltklasse','einzigartig']::text[],array['Ertragskraft','Potenzialanalyse','Deckungsbeitrag','Liquidität','Umsetzungsplan','Kennzahlen']::text[],'{"primary":"#D7182A","foreground":"#111111","background":"#FFFFFF","accent":"#000000"}'::jsonb,'brand-assets/am/logo-primary.svg',true,'0aaa0001-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.audience_segments (id, workspace_id, name, description, company_size, industries, roles, pain_points, buying_triggers, objections, sort_order, created_by) values
  ('04e96709-0000-4000-8000-000000000001','0a11b0a1-0000-4000-8000-000000000001','Geschäftsführung Handwerk, 20–80 Mitarbeitende','Inhabergeführte Handwerksbetriebe mit 20 bis 80 Mitarbeitenden. Volle Auftragsbücher, aber die Marge bleibt aus. Die Geschäftsführung steckt im Tagesgeschäft und hat keine belastbare Nachkalkulation.','20–80 Mitarbeitende',array['Elektrotechnik','SHK','Metallbau','Bauhandwerk']::text[],array['Geschäftsführung','Inhaber']::text[],array['Volle Auftragsbücher, kaum Gewinn','Keine belastbare Nachkalkulation','Preise seit Jahren nicht angepasst','Liquidität schwankt stark']::text[],array['Steuerberater meldet sinkende Marge','Erste Verlustaufträge sichtbar','Nachfolge oder Verkauf in Sicht']::text[],array['Berater kennen mein Gewerk nicht','Keine Zeit für Projekte','Habe schon einmal Geld für Beratung verbrannt']::text[],0,'0aaa0001-0000-4000-8000-000000000001'),
  ('04e96709-0000-4000-8000-000000000002','0a11b0a1-0000-4000-8000-000000000001','Geschäftsführung produzierendes Gewerbe, 50–250 Mitarbeitende','Produzierende Mittelständler mit 50 bis 250 Mitarbeitenden und gewachsener Produktvielfalt. Die Kostenstruktur ist intransparent, Deckungsbeiträge je Produktlinie sind unbekannt.','50–250 Mitarbeitende',array['Maschinenbau','Kunststoffverarbeitung','Lebensmittelproduktion','Zulieferindustrie']::text[],array['Geschäftsführung','Kaufmännische Leitung']::text[],array['Deckungsbeiträge je Produkt unbekannt','Energie- und Materialkosten gestiegen','Preiserhöhungen nicht durchsetzbar','Zu breites Sortiment']::text[],array['Bank fordert Sanierungskonzept','Rohertragsquote unter Branchenschnitt','Großkunde verhandelt Preise neu']::text[],array['Zahlen sind zu komplex für Externe','ERP-Daten sind nicht sauber','Betriebsrat könnte blockieren']::text[],1,'0aaa0001-0000-4000-8000-000000000001'),
  ('04e96709-0000-4000-8000-000000000003','0a11b0a1-0000-4000-8000-000000000001','Geschäftsführung Dienstleistung/Agentur, 15–60 Mitarbeitende','Inhabergeführte Dienstleister und Agenturen mit 15 bis 60 Mitarbeitenden. Wachstum über Umsatz, aber die Auslastung und die Projektmargen werden nicht systematisch gesteuert.','15–60 Mitarbeitende',array['Agentur','IT-Dienstleistung','Ingenieurbüro','Personaldienstleistung']::text[],array['Geschäftsführung','Partner']::text[],array['Projektmargen unbekannt','Auslastung schwankt','Zu viele Kleinkunden','Stundensätze zu niedrig']::text[],array['Wachstum ohne Gewinnsprung','Erste Kündigungen im Team','Kalkulation stimmt hinten nicht']::text[],array['Wir sind ein Sonderfall','Beratung kostet Beratungszeit','Zahlen sind im Kopf des Inhabers']::text[],2,'0aaa0001-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.services (id, workspace_id, name, description, created_by) values
  ('54f3f97f-0000-4000-8000-000000000001','0a11b0a1-0000-4000-8000-000000000001','Ertragskraft-Programm','Zwölfmonatige Begleitung zur systematischen Steigerung des Betriebsergebnisses: Nachkalkulation, Preisstrategie, Kostenstruktur, Umsetzungscontrolling.','0aaa0001-0000-4000-8000-000000000001'),
  ('54f3f97f-0000-4000-8000-000000000002','0a11b0a1-0000-4000-8000-000000000001','Kalkulations- und Preisprojekt','Aufbau einer belastbaren Vor- und Nachkalkulation samt Preisstrategie und Verhandlungsleitfaden für Bestandskunden.','0aaa0001-0000-4000-8000-000000000001') on conflict do nothing;
