insert into public.evidence_items (id, workspace_id, kind, statement, source, approved, approved_at, approved_by, numeric_value, numeric_unit, created_by) values
  ('ca12d0e3-0000-4000-8000-000000000001','0a11b0a1-0000-4000-8000-000000000001','APPROVED_STATISTIC','Über 140 begleitete mittelständische Betriebe seit 2016.','Interne Mandantenstatistik, Stand 03/2026',true,'2025-03-23T09:00:00.000Z','0aaa0001-0000-4000-8000-000000000001',140,'Betriebe','0aaa0001-0000-4000-8000-000000000001'),
  ('ca12d0e3-0000-4000-8000-000000000002','0a11b0a1-0000-4000-8000-000000000001','APPROVED_STATISTIC','Im Median 4,2 Prozentpunkte höhere Umsatzrendite nach zwölf Monaten Begleitung.','Auswertung 58 abgeschlossener Mandate 2021–2025',true,'2025-03-23T09:00:00.000Z','0aaa0001-0000-4000-8000-000000000001',4.2,'Prozentpunkte','0aaa0001-0000-4000-8000-000000000001'),
  ('ca12d0e3-0000-4000-8000-000000000003','0a11b0a1-0000-4000-8000-000000000001','HISTORICAL_PERFORMANCE','Kampagnen mit konkreter Zahl in der Headline erreichten historisch eine um 31 % höhere Formularstartrate.','Meta-Insights + First-Party-Tracking, 18 Monate',true,'2025-03-23T09:00:00.000Z','0aaa0001-0000-4000-8000-000000000001',0.31,'relativ','0aaa0001-0000-4000-8000-000000000001'),
  ('ca12d0e3-0000-4000-8000-000000000004','0a11b0a1-0000-4000-8000-000000000001','CUSTOMER_PROOF','Ein Elektrobetrieb mit 42 Mitarbeitenden steigerte den Rohertrag binnen neun Monaten um 380.000 EUR.','Mandat E-2023-114, freigegeben durch den Mandanten',true,'2025-03-23T09:00:00.000Z','0aaa0001-0000-4000-8000-000000000001',380000,'EUR','0aaa0001-0000-4000-8000-000000000001'),
  ('ca12d0e3-0000-4000-8000-000000000005','0a11b0a1-0000-4000-8000-000000000001','APPROVED_FACT','Die Erstanalyse ist kostenfrei und unverbindlich.','Leistungsbeschreibung A&M, Stand 01/2026',true,'2025-03-23T09:00:00.000Z','0aaa0001-0000-4000-8000-000000000001',null,null,'0aaa0001-0000-4000-8000-000000000001'),
  ('ca12d0e3-0000-4000-8000-000000000006','0a11b0a1-0000-4000-8000-000000000001','APPROVED_STATISTIC','Durchschnittliche Projektlaufzeit bis zum ersten messbaren Ergebnis: 11 Wochen.','Auswertung 58 abgeschlossener Mandate 2021–2025',true,'2025-03-23T09:00:00.000Z','0aaa0001-0000-4000-8000-000000000001',11,'Wochen','0aaa0001-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.case_studies (id, workspace_id, client, industry, challenge, approach, outcome, metrics, approved, usable_in_ads, created_by) values
  ('4dedea33-0000-4000-8000-000000000001','0a11b0a1-0000-4000-8000-000000000001','Elektrotechnik-Betrieb, 42 Mitarbeitende','Elektrotechnik','Auftragsbücher voll, Betriebsergebnis seit drei Jahren rückläufig. Keine Nachkalkulation, Stundensätze seit 2019 unverändert.','Nachkalkulation über 24 abgeschlossene Aufträge, Neuermittlung der Stundensätze, Preisgespräche mit den 15 größten Bestandskunden.','Rohertrag binnen neun Monaten um 380.000 EUR gesteigert, ohne einen einzigen Kunden zu verlieren.','[{"label":"Rohertrag","value":"+380.000 EUR"},{"label":"Umsatzrendite","value":"+5,1 Prozentpunkte"},{"label":"Kundenverluste","value":"0"}]'::jsonb,true,true,'0aaa0001-0000-4000-8000-000000000001'),
  ('4dedea33-0000-4000-8000-000000000002','0a11b0a1-0000-4000-8000-000000000001','Kunststoffverarbeiter, 130 Mitarbeitende','Kunststoffverarbeitung','Über 400 Artikel im Sortiment, Deckungsbeiträge je Artikel unbekannt, Energiekosten verdoppelt.','Deckungsbeitragsrechnung je Artikelgruppe, Sortimentsbereinigung, gestaffelte Preisanpassung mit Argumentationsleitfaden.','Sortiment um 27 % reduziert, EBIT-Marge von 2,1 % auf 6,8 % gesteigert.','[{"label":"EBIT-Marge","value":"2,1 % → 6,8 %"},{"label":"Artikelanzahl","value":"−27 %"}]'::jsonb,true,true,'0aaa0001-0000-4000-8000-000000000001'),
  ('4dedea33-0000-4000-8000-000000000003','0a11b0a1-0000-4000-8000-000000000001','IT-Dienstleister, 38 Mitarbeitende','IT-Dienstleistung','Starkes Umsatzwachstum, aber das Ergebnis blieb konstant. Projektmargen wurden nie gemessen.','Projektnachkalkulation, Einführung von Auslastungs- und Margensteuerung, Fokussierung auf drei Kundensegmente.','Projektmarge im Median von 9 % auf 22 % gesteigert, Auslastung stabilisiert.','[{"label":"Projektmarge (Median)","value":"9 % → 22 %"},{"label":"Auslastung","value":"68 % → 81 %"}]'::jsonb,true,false,'0aaa0001-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.testimonials (id, workspace_id, quote, author_name, author_role, company, approved, usable_in_ads, created_by) values
  ('f765d8fb-0000-4000-8000-000000000001','0a11b0a1-0000-4000-8000-000000000001','Nach zwei Terminen wussten wir zum ersten Mal, welcher Auftrag uns tatsächlich Geld bringt. Das hat unsere Preisgespräche komplett verändert.','M. Karsten','Geschäftsführer','Elektrotechnik-Betrieb, 42 Mitarbeitende',true,true,'0aaa0001-0000-4000-8000-000000000001'),
  ('f765d8fb-0000-4000-8000-000000000002','0a11b0a1-0000-4000-8000-000000000001','Kein Foliengewitter, sondern konkrete Zahlen aus unserem eigenen Betrieb. Genau das hatten wir gesucht.','S. Brehme','Inhaberin','Metallbau, 26 Mitarbeitende',true,true,'0aaa0001-0000-4000-8000-000000000001'),
  ('f765d8fb-0000-4000-8000-000000000003','0a11b0a1-0000-4000-8000-000000000001','Die Potenzialanalyse hat 40 Minuten gedauert und uns eine sechsstellige Lücke gezeigt.','T. Wieland','Geschäftsführer','Maschinenbau, 95 Mitarbeitende',true,true,'0aaa0001-0000-4000-8000-000000000001'),
  ('f765d8fb-0000-4000-8000-000000000004','0a11b0a1-0000-4000-8000-000000000001','Wir haben vorher schon einmal Geld für Beratung verbrannt. Hier war nach vier Wochen der erste Euro messbar.','A. Rennert','Partner','Ingenieurbüro, 34 Mitarbeitende',true,false,'0aaa0001-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.faqs (id, workspace_id, question, answer, approved, sort_order, created_by) values
  ('615fb6dd-0000-4000-8000-000000000001','0a11b0a1-0000-4000-8000-000000000001','Was kostet die Potenzialanalyse?','Die Erstanalyse ist kostenfrei und unverbindlich. Erst wenn wir gemeinsam ein konkretes Potenzial identifiziert haben, sprechen wir über eine Zusammenarbeit.',true,0,'0aaa0001-0000-4000-8000-000000000001'),
  ('615fb6dd-0000-4000-8000-000000000002','0a11b0a1-0000-4000-8000-000000000001','Wie viel Zeit muss ich einplanen?','Für das Erstgespräch 45 Minuten. Die Vorbereitung übernehmen wir anhand der Angaben aus dem Formular.',true,1,'0aaa0001-0000-4000-8000-000000000001'),
  ('615fb6dd-0000-4000-8000-000000000003','0a11b0a1-0000-4000-8000-000000000001','Brauche ich saubere Zahlen aus dem ERP?','Nein. Wir arbeiten mit dem, was vorhanden ist, und zeigen im Verlauf, welche Kennzahlen künftig gepflegt werden sollten.',true,2,'0aaa0001-0000-4000-8000-000000000001'),
  ('615fb6dd-0000-4000-8000-000000000004','0a11b0a1-0000-4000-8000-000000000001','Arbeiten Sie auch mit kleineren Betrieben?','Unser Programm ist auf Betriebe ab etwa 15 Mitarbeitenden ausgelegt. Darunter fehlt in der Regel die Hebelwirkung.',true,3,'0aaa0001-0000-4000-8000-000000000001'),
  ('615fb6dd-0000-4000-8000-000000000005','0a11b0a1-0000-4000-8000-000000000001','Was passiert mit meinen Daten?','Ihre Angaben werden ausschließlich zur Vorbereitung des Gesprächs verwendet und nach den Vorgaben der DSGVO verarbeitet.',true,4,'0aaa0001-0000-4000-8000-000000000001') on conflict do nothing;
