insert into public.consent_versions (id, workspace_id, version, text_de, purposes, privacy_policy_url, effective_from, created_by) values
  ('0c0e5e01-0000-4000-8000-000000000001','0a11b0a1-0000-4000-8000-000000000001',1,'Ich willige ein, dass die A&M Unternehmerberatung meine Angaben zur Vorbereitung und Durchführung eines unverbindlichen Erstgesprächs verarbeitet und mich hierzu per E-Mail oder Telefon kontaktiert. Die Einwilligung kann jederzeit mit Wirkung für die Zukunft widerrufen werden.',array['CONTACT','AD_MEASUREMENT']::text[],'https://www.am-beratung.de/datenschutz','2025-03-03T09:00:00.000Z','0aaa0001-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.angles (id, workspace_id, name, perspective, rationale, keywords, last_used_at, use_count, created_by) values
  ('6c738391-0000-4000-8000-000000000001','0a11b0a1-0000-4000-8000-000000000001','Volle Auftragsbücher, leere Kasse','Auslastung ist kein Ergebnis. Der Betrieb arbeitet viel und verdient trotzdem zu wenig.','Der Angle spricht Geschäftsführung Handwerk, 20–80 Mitarbeitende über die Diskrepanz zwischen Auslastung und Ergebnis an.',array['volle','auftragsbücher','leere','kasse']::text[],'2025-03-23T09:00:00.000Z',1,'0aaa0001-0000-4000-8000-000000000003'),
  ('6c738391-0000-4000-8000-000000000002','0a11b0a1-0000-4000-8000-000000000001','Der Vergleich, den niemand macht','Jeder kennt seinen Umsatz, kaum jemand seine Rohertragsquote im Vergleich zur Branche.','Der Angle spricht Geschäftsführung Handwerk, 20–80 Mitarbeitende über die Diskrepanz zwischen Auslastung und Ergebnis an.',array['vergleich','niemand','macht']::text[],'2025-06-21T09:00:00.000Z',1,'0aaa0001-0000-4000-8000-000000000003'),
  ('6c738391-0000-4000-8000-000000000003','0a11b0a1-0000-4000-8000-000000000001','Das teuerste Produkt ist das unbekannte','Ohne Deckungsbeitrag je Artikel subventioniert der Betrieb seine eigenen Verlustbringer.','Der Angle spricht Geschäftsführung produzierendes Gewerbe, 50–250 Mitarbeitende über die Diskrepanz zwischen Auslastung und Ergebnis an.',array['teuerste','produkt','unbekannte']::text[],'2025-09-19T09:00:00.000Z',1,'0aaa0001-0000-4000-8000-000000000003'),
